import {esc} from './engine.js';
import {searchStudio,writeWorkspaceAtomically} from './studio-model.js';
import {emptyWorkspace,validateWorkspace,saveWorkspaceProject,duplicateWorkspaceProject,removeWorkspaceProject} from './workspace-model.js';

export function createStudioUI(api){
  const KEY='design-atlas.workspace.v1';
  const labels={action:'快捷操作',site:'网站案例',block:'可玩模块',template:'整页模板',reference:'设计参考',resource:'源码资源',skill:'设计技能',theme:'主题',project:'我的项目'};
  let library=emptyWorkspace(),raw=null,problem='',lastLibrary=null,query='',filter='all',results=[],active=0,projectQuery='';
  const dialog=document.createElement('dialog');dialog.id='studio-dialog';dialog.className='studio-dialog';dialog.setAttribute('aria-label','全局搜索与项目管理');document.body.append(dialog);
  const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);
  const $=s=>dialog.querySelector(s);
  function read(){
    try{const value=localStorage.getItem(KEY);if(value!==raw)lastLibrary=null;raw=value;library=value?validateWorkspace(JSON.parse(value)):emptyWorkspace();problem='';}
    catch(error){problem='项目库暂时无法读取，原始内容已保留。请下载原始数据备份。';library=emptyWorkspace();}
    return library;
  }
  async function write(next){
    if(problem)throw Error(problem);
    const clean=validateWorkspace(next),text=JSON.stringify(clean);
    const expected=raw;await writeWorkspaceAtomically(localStorage,navigator.locks,KEY,expected,text);
    raw=text;library=clean;
    document.querySelector('#nav-projects').textContent=library.projects.length;
  }
  function close(){dialog.close();if(!document.querySelector('dialog[open]'))document.body.style.overflow='';}
  function show(){if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';}
  dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.style.overflow='';});
  dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close();}});
  const date=value=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  function items(){return [
    {id:'workspace',kind:'action',name:'打开我的项目',description:'保存的页面与方案'},
    {id:'save',kind:'action',name:'保存当前方案到项目库',description:'给当前草稿保留一份独立副本'},
    {id:'builder',kind:'action',name:'返回页面拼装台',description:'继续编辑当前草稿'},
    {id:'code',kind:'action',name:'打开源码与实时预览',description:'编辑 HTML CSS JavaScript 并导出'},
    ...api.getItems(),...library.projects.map(p=>({id:p.id,name:p.name,kind:'project',description:p.project.blocks.length+' 个模块 · '+date(p.updatedAt)}))];}
  function openSearch(){read();query='';filter='all';active=0;dialog.className='studio-dialog command-dialog';dialog.innerHTML=`<div class="command-head"><span aria-hidden="true">⌕</span><input id="global-search" type="search" role="combobox" aria-label="全局搜索" aria-controls="command-results" aria-expanded="true" aria-autocomplete="list" placeholder="找案例、模块、项目，或执行操作…" autocomplete="off"><button data-studio-action="close" aria-label="关闭搜索">Esc</button></div><div class="command-filters" aria-label="搜索范围">${[['all','全部'],['site','网站'],['block','模块'],['template','模板'],['project','项目'],['reference','参考'],['resource','资源'],['skill','技能'],['theme','主题']].map(([id,name])=>`<button data-command-filter="${id}" aria-pressed="${id==='all'}">${name}</button>`).join('')}</div><div id="command-summary" class="command-summary" aria-live="polite"></div><div id="command-results" role="listbox" aria-label="搜索结果"></div><div class="command-foot"><span>↑ ↓ 选择 · Enter 打开 · Esc 关闭</span><span>Ctrl / ⌘ K</span></div>`;
    $('#global-search').addEventListener('input',e=>{query=e.target.value;active=0;renderResults();});show();renderResults();$('#global-search').focus();}
  function renderResults(){const index=items();const initial=[...index.filter(x=>x.kind==='action'),...index.filter(x=>x.kind==='project').slice(-4).reverse(),...index.filter(x=>x.kind==='block').slice(0,4)];results=searchStudio(!query.trim()&&filter==='all'?initial:index,query,filter);active=Math.min(active,Math.max(0,results.length-1));$('#command-summary').textContent=query?`找到 ${results.length}${results.length===60?'+':''} 项匹配结果`:'从一个想法开始，或搜索全部设计资源';$('#command-results').innerHTML=results.length?results.map((x,i)=>`<button role="option" tabindex="-1" id="command-option-${i}" aria-selected="${i===active}" data-command-index="${i}" class="command-result"><span class="command-kind">${esc(labels[x.kind]||x.kind)}</span><span><b>${esc(x.name)}</b><small>${esc(x.descriptionZh||x.description||x.summary||'打开并查看')}</small></span><i aria-hidden="true">↗</i></button>`).join(''):'<div class="studio-empty"><b>没有找到这个灵感</b><p>换个关键词，或切换到「全部」。</p></div>';syncActive();}
  function syncActive(){dialog.querySelectorAll('[data-command-index]').forEach((el,i)=>el.setAttribute('aria-selected',String(i===active)));const current=$(`#command-option-${active}`);$('#global-search')?.setAttribute('aria-activedescendant',current?.id||'');current?.scrollIntoView({block:'nearest'});}
  function execute(index){const item=results[index];if(!item)return;close();if(item.kind==='action'){if(item.id==='workspace')api.navigate('projects');else if(item.id==='save')saveDialog();else if(item.id==='code')api.openCode(api.getProject());else api.navigate('builder');}else if(item.kind==='project')openProject(item.id);else api.openItem(item);}
  function saveDialog(existingId){read();const entry=existingId?library.projects.find(p=>p.id===existingId):null;if(existingId&&!entry)return;dialog.className='studio-dialog save-project-dialog';dialog.innerHTML=`<form id="save-project-form"><div class="studio-dialog-head"><div><span class="eyebrow">KEEP A GOOD IDEA</span><h2>${entry?'重命名项目':'保存一份新方案'}</h2></div><button type="button" data-studio-action="close" aria-label="关闭项目保存">×</button></div><label for="saved-project-name">方案名称</label><input id="saved-project-name" maxlength="100" required value="${esc(entry?.name||api.getProject().name)}"><p>保存的是独立副本。当前草稿仍会自动保存；之后的编辑不会覆盖库里的方案。</p>${problem?`<p role="alert">${esc(problem)}</p>`:''}<div class="studio-dialog-actions"><button type="button" class="secondary-button" data-studio-action="close">取消</button><button class="primary-button" ${problem?'disabled':''}>${entry?'保存名称':'保存到项目库'}</button></div></form>`;show();$('#saved-project-name').focus();$('#saved-project-name').select();const form=$('#save-project-form');form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('button.primary-button');if(submit.disabled)return;submit.disabled=true;try{const name=$('#saved-project-name').value.trim();if(!name)throw Error('请填写方案名称。');const p=structuredClone(entry?.project||api.getProject());p.name=name;const previous=library;await write(saveWorkspaceProject(library,p,entry?.id));lastLibrary=previous;if($('#save-project-form')===form&&dialog.open)close();api.toast(entry?'项目已重命名。':'方案已保存到「我的项目」，可以放心继续尝试。');if(api.currentView()==='projects')renderProjects(false);}catch(error){api.toast(error.message,true);}finally{submit.disabled=false;}});}
  function miniature(p){const blocks=p.blocks.filter(x=>!x.hidden).slice(0,5);return `<div class="project-miniature" style="--preview-bg:${p.theme.bg};--preview-accent:${p.theme.accent};--preview-ink:${p.theme.ink};--preview-radius:${Math.min(p.theme.radius,18)}px"><div class="miniature-nav"><i>✳</i><span></span><span></span></div>${blocks.map((b,i)=>`<div class="miniature-block ${i===1?'miniature-hero':''}"><b>${esc((b.props.title||b.props.brand||'MAKE SOMETHING YOURS').slice(0,70))}</b><span></span>${i===1?'<i>Explore ↗</i>':''}</div>`).join('')||'<div class="miniature-blank">空白画布 ✳</div>'}<small>布局示意 · ${p.blocks.length} 个模块</small></div>`;}
  function cards(){const entries=library.projects.filter(p=>p.name.toLocaleLowerCase().includes(projectQuery.toLocaleLowerCase())).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return entries.length?entries.map(p=>`<article class="project-card"><button class="project-cover" data-project-open="${esc(p.id)}" aria-label="打开项目 ${esc(p.name)}">${miniature(p.project)}</button><div class="project-card-body"><h3><button data-project-open="${esc(p.id)}">${esc(p.name)}</button></h3><p>${p.project.blocks.length} 个模块 · ${date(p.updatedAt)}</p><div class="project-card-actions"><button class="primary-button" data-project-open="${esc(p.id)}">继续设计 ↗</button><button class="icon-btn" data-project-rename="${esc(p.id)}" aria-label="重命名 ${esc(p.name)}" title="重命名">✎</button><button class="icon-btn" data-project-duplicate="${esc(p.id)}" aria-label="复制项目 ${esc(p.name)}" title="复制">⧉</button><button class="icon-btn" data-project-download="${esc(p.id)}" aria-label="下载项目 ${esc(p.name)}" title="下载 JSON">↓</button><button class="icon-btn" data-project-remove="${esc(p.id)}" aria-label="移除项目 ${esc(p.name)}" title="移除，可撤销">×</button></div></div></article>`).join(''):`<div class="studio-empty"><span>✳</span><h2>${projectQuery?'没有匹配的项目':'给每个好想法，留一个位置。'}</h2><p>${projectQuery?'换个名称试试。':'把当前草稿存成方案，再复制一份探索另一种方向。'}</p>${projectQuery?'':'<button class="primary-button" data-studio-action="save">保存当前草稿 ↗</button>'}</div>`;}
  function renderProjects(refresh=true){if(refresh)read();api.root.innerHTML=`<section class="projects-view"><div class="projects-heading"><div><span class="page-eyebrow">YOUR IDEAS, WITH ROOM TO GROW</span><h1>好想法，不必只留一个。</h1><p>每个方案独立保存。打开、复制，继续做下一次尝试。</p></div><button class="primary-button" data-studio-action="save">＋ 保存当前草稿</button></div><div class="current-draft"><span class="draft-mark">✳</span><div><small>正在编辑的草稿 · 浏览器自动保存</small><h2>${esc(api.getProject().name)}</h2><p>${api.getProject().blocks.length} 个模块 · ${esc(api.getProject().theme.name||'自定义主题')}</p></div><button class="secondary-button" data-view="builder">继续编辑 ↗</button></div><div class="projects-toolbar"><label class="search-box"><span>⌕</span><input id="project-library-search" type="search" aria-label="搜索我的项目" placeholder="搜索保存的方案…" value="${esc(projectQuery)}"></label><span>${library.projects.length} / 24 份方案</span><button class="secondary-button" data-studio-action="undo-library" ${lastLibrary?'':'disabled'}>撤销库修改</button><button class="secondary-button" data-studio-action="import-library">导入项目库</button><button class="secondary-button" data-studio-action="export-library">导出项目库</button></div>${problem?`<div class="studio-warning" role="alert">${esc(problem)} <button data-studio-action="recover">下载原始数据</button></div>`:''}<div class="projects-grid" id="projects-grid">${cards()}</div><p class="projects-note">项目库保存在当前浏览器，最多 24 份方案。打开方案会切换当前草稿，可在拼装台一步撤销；跨设备使用请导出 JSON。</p></section>`;document.querySelector('#nav-projects').textContent=library.projects.length;document.querySelector('#project-library-search').addEventListener('input',e=>{projectQuery=e.target.value;document.querySelector('#projects-grid').innerHTML=cards();});}
  function openProject(id){read();const entry=library.projects.find(p=>p.id===id);if(!entry){api.toast('这个项目已不存在，请刷新项目库。',true);return}api.loadProject(structuredClone(entry.project));api.toast('已打开方案。上一份草稿可在拼装台撤销恢复。');}
  async function performEdit(fn){try{const previous=library;await write(fn(library));lastLibrary=previous;if(api.currentView()==='projects')renderProjects(false);}catch(error){api.toast(error.message,true);}}
  document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
    if(b.dataset.commandFilter){filter=b.dataset.commandFilter;active=0;dialog.querySelectorAll('[data-command-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderResults();$('#global-search').focus();return}
    if(b.dataset.commandIndex!==undefined){execute(Number(b.dataset.commandIndex));return}
    if(b.dataset.projectOpen){openProject(b.dataset.projectOpen);return}
    if(b.dataset.projectRename){saveDialog(b.dataset.projectRename);return}
    if(b.dataset.projectDuplicate){performEdit(l=>duplicateWorkspaceProject(l,b.dataset.projectDuplicate));return}
    if(b.dataset.projectRemove){performEdit(l=>removeWorkspaceProject(l,b.dataset.projectRemove));return}
    if(b.dataset.projectDownload){const p=library.projects.find(p=>p.id===b.dataset.projectDownload);if(p)api.download(JSON.stringify(p.project,null,2),p.name.replace(/[<>:"/\\|?*]/g,'-')+'.atlas.json','application/json');return}
    const action=b.dataset.studioAction;if(!action)return;
    if(action==='search')openSearch();else if(action==='close')close();else if(action==='save')saveDialog();else if(action==='import-library'){read();input.click();}else if(action==='export-library'){read();if(problem){api.toast(problem,true);return}api.download(JSON.stringify(library,null,2),'design-atlas.workspace.json','application/json');}else if(action==='recover'){api.download(raw||'','design-atlas.workspace-recovery.txt');}else if(action==='undo-library'&&lastLibrary){try{const restore=lastLibrary;await write(restore);lastLibrary=null;if(api.currentView()==='projects')renderProjects(false);api.toast('最近一次项目库修改已撤销。');}catch(error){api.toast(error.message,true);}}
  });
  dialog.addEventListener('keydown',e=>{if(!$('#global-search'))return;if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();active=e.key==='Home'?0:e.key==='End'?Math.max(0,results.length-1):(active+(e.key==='ArrowDown'?1:-1)+results.length)%Math.max(1,results.length);syncActive();}else if(e.key==='Enter'&&e.target===$('#global-search')){e.preventDefault();execute(active);}});
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!e.altKey){if(document.querySelector('dialog[open]')&&!dialog.open)return;e.preventDefault();dialog.open?close():openSearch();}});
  input.addEventListener('change',async()=>{const file=input.files[0];input.value='';if(!file)return;try{if(file.size>6*1024*1024)throw Error('项目库文件超过 6 MiB。');const incoming=validateWorkspace(JSON.parse(await file.text()));const previous=library,merged=structuredClone(library);for(const entry of incoming.projects){const found=merged.projects.find(p=>p.id===entry.id);if(found&&JSON.stringify(found)!==JSON.stringify(entry))throw Error('同一项目 ID 存在不同内容，未导入。请先在来源库复制为新方案。');if(!found)merged.projects.push(entry);}await write(merged);lastLibrary=previous;if(api.currentView()==='projects')renderProjects(false);api.toast('项目库已合并，原有方案保留。');}catch(error){api.toast('导入失败：'+error.message,true);}});
  read();return {openSearch,saveDialog,renderProjects,count:()=>library.projects.length};
}
